#include <stdio.h>

int main(void)
{
    int cap=5;
    for(int n=1;n<=7;n++){if(n*10>cap*6){cap=cap*2+1;}}
    printf("%d\n",cap);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int parent[]={-1,0,0,1},count=0;
    for(int v=3;parent[v]!=-1;v=parent[v]){count++;}
    printf("%d\n",count);
    return 0;
}

